<script setup lang="ts">
import { computed, useId } from 'vue'
import type { OverviewTrack } from '../data/overview'
import { overviewLabels, overviewPointUtc } from '../data/overview-window'
import { regionLongitude, type BasinRegion } from '../data/basin'
import { geographicPaths } from '../data/map-geography'
const props=defineProps<{tracks:OverviewTrack[];region:BasinRegion;base:string;cyclone:string}>()
const clip='overview-'+useId().replace(/:/g,'')
const x=(lon:number)=>65+(regionLongitude(lon,props.region)-props.region.west)/(props.region.east-props.region.west)*1470
const y=(lat:number)=>95+(props.region.north-lat)/(props.region.north-props.region.south)*900
const lands=computed(()=>geographicPaths('land',props.region)),borders=computed(()=>geographicPaths('borders',props.region))
const geographyTransform='translate(-17.1,1.14) scale(1.3243243,1.1042945)'
const extra=computed(()=>Math.max(0,Math.ceil(props.tracks.length/4)-1)*86),height=computed(()=>1190+extra.value)
const isMean=(t:OverviewTrack)=>(t.kind??'ensemble')==='ensemble'
const trackKind=(t:OverviewTrack)=>t.kind==='derived'?'Local MSLP L track · not provider TC guidance':isMean(t)?'Ensemble mean':'Single track · not ensemble mean'
const lons=computed(()=>Array.from({length:Math.max(0,Math.floor(props.region.east/5)-Math.ceil(props.region.west/5)+1)},(_,i)=>(Math.ceil(props.region.west/5)+i)*5))
const lats=computed(()=>Array.from({length:Math.max(0,Math.floor(props.region.north/5)-Math.ceil(props.region.south/5)+1)},(_,i)=>(Math.ceil(props.region.south/5)+i)*5))
const curves=computed(()=>props.tracks.map(t=>({...t,segments:t.points.slice(1).flatMap((p,i)=>{const a=t.points[i]!;return p.leadHours>a.leadHours&&p.leadHours-a.leadHours<=12&&Math.abs(regionLongitude(p.lon,props.region)-regionLongitude(a.lon,props.region))<180?[{a,p}]:[]})})))
const labels=computed(()=>overviewLabels(props.tracks,props.base,p=>({x:x(p.lon),y:y(p.lat)})))
const end=computed(()=>{const times=props.tracks.flatMap(t=>t.points.map(p=>Date.parse(overviewPointUtc(props.base,p))));return times.length?new Date(Math.max(...times)).toISOString():props.base})
function lonLabel(lon:number){const n=((lon+180)%360+360)%360-180;return `${Math.abs(n)}°${n<0?'W':'E'}`}
</script>
<template>
<svg class="track-overview-plot" :viewBox="`0 0 1600 ${height}`" xmlns="http://www.w3.org/2000/svg" role="img" :aria-label="`${cyclone} multi-model forecast track overview`" style="background:white;font-family:Arial,sans-serif">
<title>{{ cyclone }} · Multi-Model Tropical Cyclone Track Forecast Overview</title><desc>Actual source fixes only, clipped to one absolute UTC display window; no synthetic boundary points, no smoothing, extrapolation or source-cycle splicing. Model positions/intensities and source bases remain unchanged. Date labels show each native +h together with valid UTC; common-anchor hours are not native lead hours. Original ATCF ensemble means remain distinct from WMC individual paths, SD3 native paths and AIGFS locally derived MSLP L centres. Source identity crosswalks are explicitly local/nonofficial and never inferred from ID suffixes. WMC uses legacy HTTP without TLS integrity; point UTC, not inconsistent wrapper epoch or production time. AIGFS L is not supplier-issued TC guidance or verified tropical structure; no inferred wind or Cat. SD3 directory version and NetCDF first valid UTC are distinct, not an undocumented initialization. {{ tracks.map(t=>`${t.label}: ${trackKind(t)}; ${isMean(t)?'ensemble statistic':'no ensemble N/probability'}; ${t.identity??cyclone}; ${t.initializationLabel??'provider/model run'} ${t.initialization}; ${t.baseLabel??'forecast base'} ${t.forecastZero}; ${t.source}; ${t.provenance??''}; `+t.points.map(p=>`${overviewPointUtc(base,p)} native +${(Date.parse(overviewPointUtc(base,p))-Date.parse(t.forecastZero))/3600000}h ${p.lat},${p.lon} ${!isMean(t)?`raw wind=${p.windMs??'missing'} m/s pressure=${p.pressureHpa??'missing'} hPa`:`n=${p.count}`}`).join('; ')).join(' | ') }} No cones or landfall markers.</desc>
<rect :height="height" width="1600" fill="white"/><rect x="65" y="95" width="1470" height="900" fill="#edfaff"/><defs><clipPath :id="clip"><rect x="65" y="95" width="1470" height="900"/></clipPath></defs>
<text x="800" y="33" font-size="27" text-anchor="middle" font-weight="bold">Multi-Model Tropical Cyclone Track Forecast Overview</text><text x="800" y="63" font-size="21" text-anchor="middle">{{ cyclone }} · UTC {{ base.slice(0,16) }}Z → {{ end.slice(0,16) }}Z</text>
<g :clip-path="`url(#${clip})`"><g :transform="geographyTransform"><path v-for="(p,i) in lands" :key="'l'+i" :d="p" fill="#faf6ed" stroke="#8d8b80" stroke-width=".85"/><path v-for="(p,i) in borders" :key="'b'+i" :d="p" fill="none" stroke="#b3a994" stroke-width=".7"/></g><g stroke="#a6bdc7" stroke-width=".7" stroke-dasharray="2 3"><line v-for="v in lons" :key="'x'+v" :x1="x(v)" :x2="x(v)" y1="95" y2="995"/><line v-for="v in lats" :key="'y'+v" x1="65" x2="1535" :y1="y(v)" :y2="y(v)"/></g>
<g v-for="t in curves" :key="t.model" class="overview-model" :data-model="t.model" :data-kind="t.kind??'ensemble'"><line v-for="s in t.segments" :key="s.p.leadHours" :x1="x(s.a.lon)" :y1="y(s.a.lat)" :x2="x(s.p.lon)" :y2="y(s.p.lat)" :stroke="t.color" stroke-width="3.2" stroke-linecap="round"/><g v-for="p in t.points.filter((p,i)=>i===0||i===t.points.length-1||Date.parse(overviewPointUtc(base,p))%86400000===0)" :key="p.leadHours"><rect :x="x(p.lon)-4" :y="y(p.lat)-4" width="8" height="8" :fill="t.color"/><title>{{ t.label }} · {{ overviewPointUtc(base,p) }} · native +{{ (Date.parse(overviewPointUtc(base,p))-Date.parse(t.forecastZero))/3600000 }}h · {{ !isMean(t)?`${trackKind(t)} · ${t.identity} · raw ${p.windMs??'missing'} m/s · ${p.pressureHpa??'missing'} hPa`:`n=${p.count}` }}</title></g></g>
<g class="overview-utc-labels"><text v-for="p in labels" :key="p.model+p.utc" :x="x(p.point.lon)+9" :y="y(p.point.lat)-9" font-size="17" :fill="p.color" stroke="white" stroke-width="4" paint-order="stroke">{{ p.text }}<title>{{ p.model }} · {{ p.utc }}</title></text></g></g>
<rect x="65" y="95" width="1470" height="900" fill="none" stroke="#52666d" stroke-width="1.8"/><g font-size="18"><text v-for="v in lons" :key="v" :x="x(v)" y="1022" text-anchor="middle">{{ lonLabel(v) }}</text><text v-for="v in lats" :key="v" x="55" :y="y(v)+5" text-anchor="end">{{ Math.abs(v) }}°{{ v<0?'S':'N' }}</text></g>
<g v-for="(t,i) in tracks" :key="t.model" class="overview-legend-entry" :transform="`translate(${70+(i%4)*380},${1055+Math.floor(i/4)*86})`"><line x2="32" :stroke="t.color" stroke-width="4"/><text x="42" y="6" font-size="19" :fill="t.color">{{ t.label }}</text><text y="25" font-size="13" fill="#58677c">{{ isMean(t)?'Ensemble mean':t.kind==='derived'?'Local L · not TC guidance':'Single track · no ensemble N' }}</text><text y="43" font-size="13" fill="#58677c">{{ t.initializationLabel??(t.model==='wm6'?'Provider run:':'Model init:') }} {{ t.initialization }}</text><text y="61" font-size="13" fill="#58677c">{{ t.baseLabel??'Forecast base:' }} {{ t.forecastZero }}</text><title>{{ t.identity??cyclone }} · {{ t.provenance }}</title></g>
<text x="70" :y="height-40" font-size="14" fill="#596a7c">Solid curves · Date labels = valid UTC · Native/model bases remain separate · No cross-model consensus · Natural Earth 1:50m</text><text x="70" :y="height-18" font-size="14" fill="#596a7c">{{ tracks.some(t=>t.model==='SD3')?'SD3: TianJi Weather Science and Technology Company · https://www.tjweather.com · CC BY-NC 4.0 · https://creativecommons.org/licenses/by-nc/4.0/ · Noncommercial only':'Local reference, not an official warning. Missing models / ended tracks are not filled or extended.' }}</text>
</svg>
</template>
<style scoped>.track-overview-plot{width:100%;height:auto;display:block}</style>
